import * as Print from "expo-print";
import * as Sharing from "expo-sharing";
import { Alert } from "react-native";
import type { TimelineEvent } from "@/lib/petTimeline";

// Brand colours — match the app exactly.
const BRAND = "#0e6e56";
const BRAND_LIGHT = "#92bdb3";
const TEXT = "#1a1a1a";
const MUTED = "#666666";

// Event-kind colours, matching the app's KIND_META exactly.
const KIND_COLORS: Record<string, string> = {
  weight: "#10b981", symptom: "#f59e0b", condition: "#ef4444",
  vaccination: "#3b82f6", medication: "#06b6d4", referral: "#8b5cf6",
  birth: "#0e6e56", birthday: "#0e6e56",
};
const KIND_LABELS: Record<string, string> = {
  weight: "Weight", symptom: "Symptom", condition: "Diagnosis",
  vaccination: "Vaccination", medication: "Medication", referral: "Referral",
  birth: "Born", birthday: "Birthday",
};

// White Rufferral wordmark, embedded inline (base64) — no external file dependency.
const LOGO_BASE64 = "";

function formatDate(iso: string | null | undefined): string {
  if (!iso) return "";
  try {
    return new Date(iso).toLocaleDateString("en-AU", { day: "numeric", month: "short", year: "numeric" });
  } catch { return iso; }
}
function escapeHtml(text: string | number | null | undefined): string {
  if (text === null || text === undefined || text === "") return "";
  return String(text).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}
function calculateAge(dob: string): string {
  const birth = new Date(dob);
  const now = new Date();
  let years = now.getFullYear() - birth.getFullYear();
  let months = now.getMonth() - birth.getMonth();
  if (months < 0) { years--; months += 12; }
  if (years === 0) return `${months} month${months !== 1 ? "s" : ""}`;
  if (months === 0) return `${years} year${years !== 1 ? "s" : ""}`;
  return `${years} year${years !== 1 ? "s" : ""}, ${months} month${months !== 1 ? "s" : ""}`;
}

export type PetExportData = {
  name: string;
  species?: string | null; breed?: string | null; sex?: string | null;
  dateOfBirth?: string | null; microchipNumber?: string | null;
  latestWeightKg?: number | null;
  ownerName?: string | null; ownerEmail?: string | null; ownerPhone?: string | null;
  foodBrand?: string | null; foodType?: string | null; foodAmountGrams?: number | null;
  feedingFrequency?: number | null; treats?: string | null; supplements?: string | null;
  foodSensitivities?: string | null;
  exerciseDurationMins?: number | null; exerciseTypes?: string | null;
  livingSituation?: string | null; backyardAccess?: boolean | null;
  otherPets?: string | null; temperament?: string | null; trainingLevel?: string | null;
  vaccinationStatus?: string | null; desexedDate?: string | null;
  acquisitionSource?: string | null;
  insuranceProvider?: string | null; insurancePolicyNumber?: string | null;
};

function infoRow(label: string, value: string | number | null | undefined): string {
  if (value === null || value === undefined || value === "") return "";
  return `<tr><td class="info-label">${escapeHtml(label)}</td><td class="info-value">${escapeHtml(value)}</td></tr>`;
}

// Small colored pill matching the app's timeline label treatment (white text on
// the event-kind color; a muted pill for the white/"birth" kind).
function pill(text: string, bgColor: string): string {
  return `<span class="pill" style="background:${bgColor};">${escapeHtml(text)}</span>`;
}

function buildHtml(pet: PetExportData, events: TimelineEvent[], reminders?: Record<string, { reminder_date: string }>): string {
  const today = formatDate(new Date().toISOString());
  const age = pet.dateOfBirth ? calculateAge(pet.dateOfBirth) : null;

  const conditions = events.filter(e => e.kind === "condition").map(e => ({ text: e.subtitle || e.title, date: formatDate(e.date) }));
  const medications = events.filter(e => e.kind === "medication").map(e => ({ text: e.subtitle ? `${e.title} — ${e.subtitle}` : e.title, date: formatDate(e.date) }));
  const vaccinations = events.filter(e => e.kind === "vaccination").map(e => {
    const vacId = e.id.replace("vaccination:", "");
    const reminder = reminders?.[vacId];
    return { text: e.subtitle || e.title, date: formatDate(e.date), reminderDate: reminder ? formatDate(reminder.reminder_date) : null };
  });

  const petDetailsRows = [
    infoRow("Species", pet.species), infoRow("Breed", pet.breed), infoRow("Sex", pet.sex),
    infoRow("Date of birth", pet.dateOfBirth ? `${formatDate(pet.dateOfBirth)} (${age})` : null),
    infoRow("Microchip", pet.microchipNumber),
    infoRow("Current weight", pet.latestWeightKg != null ? `${pet.latestWeightKg} kg` : null),
    infoRow("Desexed", pet.desexedDate ? formatDate(pet.desexedDate) : null),
    infoRow("Vaccination status", pet.vaccinationStatus),
    infoRow("Acquired via", pet.acquisitionSource),
  ].join("");

  const ownerRows = [infoRow("Name", pet.ownerName), infoRow("Email", pet.ownerEmail), infoRow("Phone", pet.ownerPhone)].join("");

  const nutritionRows = [
    infoRow("Food brand", pet.foodBrand), infoRow("Food type", pet.foodType),
    infoRow("Amount per feed", pet.foodAmountGrams != null ? `${pet.foodAmountGrams} g` : null),
    infoRow("Feeding frequency", pet.feedingFrequency != null ? `${pet.feedingFrequency}x per day` : null),
    infoRow("Treats", pet.treats), infoRow("Supplements", pet.supplements),
    infoRow("Food sensitivities", pet.foodSensitivities),
  ].join("");

  const lifestyleRows = [
    infoRow("Exercise", pet.exerciseDurationMins != null ? `${pet.exerciseDurationMins} min/day` : null),
    infoRow("Exercise types", pet.exerciseTypes), infoRow("Living situation", pet.livingSituation),
    infoRow("Backyard access", pet.backyardAccess === true ? "Yes" : pet.backyardAccess === false ? "No" : null),
    infoRow("Other pets", pet.otherPets), infoRow("Temperament", pet.temperament),
    infoRow("Training level", pet.trainingLevel),
  ].join("");

  const insuranceRows = [infoRow("Provider", pet.insuranceProvider), infoRow("Policy number", pet.insurancePolicyNumber)].join("");

  const section = (title: string, rows: string) =>
    rows ? `<table class="section-block" role="presentation"><tr><td>
      <div class="section">
        <h2>${escapeHtml(title)}</h2>
        <table class="info-table">${rows}</table>
      </div>
    </td></tr></table>` : "";

  const listSection = (title: string, items: { text: string; date: string; reminderDate?: string | null }[]) =>
    items.length > 0 ? `<table class="section-block" role="presentation"><tr><td>
      <div class="section">
        <h2>${escapeHtml(title)}</h2>
        ${items.map(i => `
          <table class="list-row" role="presentation"><tr><td>
            <span class="list-text">${escapeHtml(i.text)}</span>
            <span class="date">${i.date}</span>
            ${i.reminderDate ? pill(`Next due ${i.reminderDate}`, "#3b82f6") : ""}
          </td></tr></table>
        `).join("")}
      </div>
    </td></tr></table>` : "";

  const timelineHtml = events.map(e => {
    const color = KIND_COLORS[e.kind] ?? BRAND;
    const label = KIND_LABELS[e.kind] ?? e.kind;
    return `
    <table class="tl-row" role="presentation"><tr>
      <td class="tl-dot-cell"><div class="tl-dot" style="background:${color};"></div></td>
      <td class="tl-content-cell">
        <div class="tl-date">${formatDate(e.date)} ${pill(label, color)}</div>
        <div class="tl-title">${escapeHtml(e.title)}</div>
        ${e.subtitle ? `<div class="tl-subtitle">${escapeHtml(e.subtitle)}</div>` : ""}
      </td>
    </tr></table>`;
  }).join("");

  return `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8" />
<style>
  @page { margin: 28px 32px; }
  * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; color-adjust: exact !important; }
  html, body { margin: 0; padding: 0; }
  body { font-family: -apple-system, Helvetica, Arial, sans-serif; color: ${TEXT}; font-size: 12px; line-height: 1.55; background: #ffffff; }

  /* Header: table-based so the background colour reliably prints, and it
     repeats correctly at the top of the content flow. */
  .header-table { width: 100%; background: ${BRAND} !important; border-collapse: collapse; margin-bottom: 22px; }
  .header-table td { padding: 20px 24px; }
  .pet-name { font-size: 22px; color: #ffffff !important; font-weight: 700; }
  .pet-subtitle { font-size: 10px; color: ${BRAND_LIGHT} !important; margin-top: 3px; }
  .logo-cell { text-align: right; vertical-align: middle; }
  .logo { height: 24px; }

  .section-block { width: 100%; border-collapse: collapse; page-break-inside: avoid; }
  .section { margin-bottom: 16px; }
  .section h2 { font-size: 12px; font-weight: 700; color: ${BRAND}; text-transform: uppercase; letter-spacing: 0.5px; margin: 0 0 6px 0; padding-bottom: 3px; border-bottom: 1px solid ${BRAND_LIGHT}; }
  .info-table { width: 100%; border-collapse: collapse; }
  .info-table td { font-size: 12px; vertical-align: top; padding: 2px 0; }
  .info-label { color: ${MUTED}; width: 150px; }
  .info-value { color: ${TEXT}; }

  .list-row { width: 100%; border-collapse: collapse; page-break-inside: avoid; }
  .list-row td { padding: 2px 0; font-size: 12px; }
  .list-text { color: ${TEXT}; }
  .date { color: ${MUTED}; font-size: 10px; margin-left: 8px; }

  /* Pill — same visual language as the app's colored event/status labels. */
  .pill { display: inline-block; color: #ffffff !important; font-size: 9px; font-weight: 700; padding: 2px 7px; border-radius: 6px; margin-left: 6px; }

  .tl-row { width: 100%; border-collapse: collapse; page-break-inside: avoid; margin-bottom: 2px; }
  .tl-dot-cell { width: 20px; vertical-align: top; padding-top: 5px; }
  .tl-dot { width: 9px; height: 9px; border-radius: 50%; }
  .tl-content-cell { vertical-align: top; padding-bottom: 9px; }
  .tl-date { font-size: 10px; color: ${MUTED}; margin-bottom: 1px; }
  .tl-title { font-size: 12px; font-weight: 600; color: ${TEXT}; }
  .tl-subtitle { font-size: 11px; color: ${MUTED}; }

  .content { padding: 0 32px; }
  .footer { margin-top: 18px; padding-top: 10px; border-top: 1px solid ${BRAND_LIGHT}; font-size: 9px; color: ${MUTED}; text-align: center; }
</style>
</head>
<body>
  <table class="header-table" role="presentation"><tr>
    <td>
      <div class="pet-name">${escapeHtml(pet.name)}</div>
      <div class="pet-subtitle">Pet Health Record — exported ${today}</div>
    </td>
    <td class="logo-cell"><img class="logo" src="data:image/png;base64,${LOGO_BASE64}" /></td>
  </tr></table>

  <div class="content">
    ${section("Pet Details", petDetailsRows)}
    ${section("Owner", ownerRows)}
    ${section("Nutrition", nutritionRows)}
    ${section("Exercise & Lifestyle", lifestyleRows)}
    ${section("Insurance", insuranceRows)}
    ${listSection("Conditions / Diagnoses", conditions)}
    ${listSection("Medications", medications)}
    ${listSection("Vaccinations", vaccinations)}

    <div class="section">
      <h2>Lifetime Timeline</h2>
      ${timelineHtml}
    </div>

    <div class="footer">Generated by Rufferral — rufferral.com — ${today}</div>
  </div>
</body>
</html>`;
}

export async function exportPetPdf(
  pet: PetExportData,
  events: TimelineEvent[],
  reminders?: Record<string, { reminder_date: string }>,
) {
  try {
    const html = buildHtml(pet, events, reminders);
    const { uri } = await Print.printToFileAsync({ html, base64: false });
    if (await Sharing.isAvailableAsync()) {
      await Sharing.shareAsync(uri, { mimeType: "application/pdf", dialogTitle: `${pet.name}'s Health Record`, UTI: "com.adobe.pdf" });
    } else {
      Alert.alert("PDF saved", `The PDF was saved to:\n${uri}`);
    }
  } catch (err: any) {
    Alert.alert("Export failed", err?.message ?? "Something went wrong generating the PDF.");
  }
}
